const fs = require('fs');
const path = require('path');
const cache = path.resolve('.orchestra/tasks/V-1277/refresh/npm-cache/_npx');
const root = fs.readdirSync(cache).map(d => path.join(cache, d, 'node_modules')).find(d => fs.existsSync(path.join(d, 'tailwindcss')) && fs.existsSync(path.join(d, 'postcss')));
if (!root) throw new Error('Cached postcss for CSS review missing');
const postcss = require(path.join(root, 'postcss'));
const previous = fs.readFileSync('.orchestra/tasks/V-1277/tailwind.before.css', 'utf8');
const current = fs.readFileSync('app/static/css/vendor/tailwind.css', 'utf8');
const index = text => {
  const result = new Map();
  postcss.parse(text).walkRules(rule => {
    const ancestors = [];
    for (let parent = rule.parent; parent && parent.type !== 'root'; parent = parent.parent) ancestors.unshift(parent.name + ' ' + parent.params);
    result.set(ancestors.join(' / ') + ' | ' + rule.selector, rule.nodes.map(n => n.toString()).join(';'));
  });
  return result;
};
const before = index(previous), after = index(current);
const added = [...after.keys​()].filter(k => !before.has(k));
const removed = [...before.keys​()].filter(k => !after.has(k));
const changed = [...after.keys​()].filter(k => before.has(k) && before.get(k) !== after.get(k));
console.log(JSON.stringify({beforeBytes: Buffer.byteLength(previous), afterBytes: Buffer.byteLength(current), added, removed, changed}, null, 2));
for (const key of added) console.log('ADDED', key​, after.get(key​));
